namespace ghidra.app.util.viewer.field;




using ghidra.app.nav;
using ghidra.app.util;
using ghidra.app.util.query;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.program.util;

/**
 * A handler to process {@link VariableXRefFieldLocation} clicks
 */
public class VariableXRefFieldMouseHandler : XRefFieldMouseHandler {

	private static Class<object>[] SUPPORTED_CLASSES =
		new Class<object>[] { typeof(VariableXRefFieldLocation), typeof(VariableXRefHeaderFieldLocation) };

	/* @Override */
	protected Address getFromReferenceAddress(ProgramLocation programLocation) {
		return programLocation.getRefAddress();
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}

	/* @Override */
	protected bool isXREFHeaderLocation(ProgramLocation location) {
		return location is VariableXRefHeaderFieldLocation;
	}

	/* @Override */
	protected void showXRefDialog(Navigatable navigatable, ProgramLocation location,
			ServiceProvider serviceProvider) {
		TableService service = serviceProvider.getService(typeof(TableService));
		if (service == null) {
			return;
		}

		VariableLocation variableLocation = (VariableLocation) location;
		Variable variable = variableLocation.getVariable();

		Supplier<Collection<Reference>> refs = () => getVariableRefs(variable);
		XReferenceUtils.showXrefs(navigatable, serviceProvider, service, location, refs);
	}

	private Set<Reference> getVariableRefs(Variable var) {

		Set<Reference> results = new();
		Address addr = var.getMinAddress();
		if (addr == null) {
			return results;
		}

		Program program = var.getFunction().getProgram();
		ReferenceManager refMgr = program.getReferenceManager();
		Reference[] refs = refMgr.getReferencesTo(var);
		foreach (Reference vref in refs) {
			results.add(vref);
		}
		return results;
	}
}
